refsection.programlisting:
scicv_Init();

img = imread(getSampleImage("lena.jpg"));

// Resize to a [100, 100] pixels image
img_100x100 = resize(img, [100, 100]);

subplot(1,2,1);
matplot(img_100x100);

// Resize to a half size image
img_half = resize(img, 0, 0.5, 0.5);

subplot(1,2,2);
matplot(img_half);

delete_Mat(img);
delete_Mat(img_100x100);
delete_Mat(img_half);
